#include <map>
#include <vector>
#include <string>
class LSMTree {
public:
    std::map<std::string, std::string> memtable;
    std::vector<std::map<std::string, std::string>> sstables;
    void put(const std::string& k, const std::string& v) {
        memtable[k] = v;
        if (memtable.size() >= 3) { sstables.push_back(memtable); memtable.clear(); }
    }
    std::string get(const std::string& k) {
        if (memtable.count(k)) return memtable[k];
        for (auto it = sstables.rbegin(); it != sstables.rend(); ++it) { if (it->count(k)) return (*it)[k]; }
        return "";
    }
};

