class BTreeIndex {
public:
    std::vector<std::string> keys, values;
    void put(const std::string& k, const std::string& v) { keys.push_back(k); values.push_back(v); }
    std::string get(const std::string& k) {
        auto it = std::find(keys.begin(), keys.end(), k);
        return it != keys.end() ? values[std::distance(keys.begin(), it)] : "";
    }
};

