#include <vector>
#include <string>
class Participant { public: virtual bool prepare(unsigned long tx) = 0; virtual void commit(unsigned long tx) = 0; virtual void abort(unsigned long tx) = 0; };
class Coordinator2PC {
    std::vector<Participant*> participants;
public:
    Coordinator2PC(std::vector<Participant*> p) : participants(p) {}
    std::string commit_tx(unsigned long tx) {
        for (auto* p : participants) { if (!p->prepare(tx)) { for (auto* p2 : participants) p2->abort(tx); return "Aborted"; } }
        for (auto* p : participants) p->commit(tx);
        return "Committed";
    }
};

#include <vector>
#include <string>
#include <numeric>
class HashRouter {
    std::vector<std::string> nodes;
public:
    HashRouter(int n=3) { for (int i=0; i<n; ++i) nodes.push_back("Node-" + std::to_string(i)); }
    std::string route(const std::string& key) {
        unsigned int sum = std::accumulate(key.begin(), key.end(), 0);
        return nodes[sum % nodes.size()];
    }
};

