struct RangeBoundary { std::string start, end, node; };
class RangeRouter {
    std::vector<RangeBoundary> boundaries;
public:
    std::string route(const std::string& key) {
        for (const auto& b : boundaries) { if (key >= b.start && key <= b.end) return b.node; }
        return "Node-Fallback";
    }
};

