class ProtobufEncoder {
public:
    static std::vector<unsigned char> encode_field(unsigned int tag, unsigned int type, const std::string& val) {
        std::vector<unsigned char> buf; buf.push_back((tag << 3) | type);
        buf.insert(buf.end(), val.begin(), val.end()); return buf;
    }
};

