class SingleLeaderDB {
public:
    std::map<std::string, std::string> leader;
    std::vector<std::map<std::string, std::string>> replicas;
    void write(const std::string& k, const std::string& v) {
        leader[k] = v; for (auto& r : replicas) r[k] = v;
    }
    std::string read(const std::string& k) { return replicas[0][k]; }
};

