#include <vector>
template<typename T>
class LinuxKfifo {
    std::vector<T> buffer; unsigned int size, in_idx = 0, out_idx = 0;
public:
    LinuxKfifo(unsigned int s) : size(s), buffer(s) {}
    bool put(T val) { buffer[in_idx++ & (size - 1)] = val; return true; }
    T get() { return buffer[out_idx++ & (size - 1)]; }
};

